mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM marketplace_entity_versions
WHERE entity_type = #{entityType} AND entity_id = #{entityId}

mapper.insert:
INSERT INTO marketplace_entity_versions (
    id, entity_type, entity_id, version_no, action, snapshot, changed_fields,
    actor_user_id, actor_type, reason, restored_from_version_id, created_at
) VALUES (
    #{id}, #{entityType}, #{entityId}, #{versionNo}, #{action}, #{snapshot}::jsonb,
    #{changedFields}::jsonb, #{actorUserId}, #{actorType}, #{reason},
    #{restoredFromVersionId}, #{createdAt}
)

INSERT INTO marketplace_audit_events (
    id, organization_id, entity_type, entity_id, action, actor_user_id,
    actor_type, reason, metadata, request_id, created_at
) VALUES (
    #{id}, #{organizationId}, #{entityType}, #{entityId}, #{action}, #{actorUserId},
    #{actorType}, #{reason}, #{metadata}::jsonb, #{requestId}, #{createdAt}
)

mapper.select:
SELECT * FROM marketplace_entity_versions
WHERE entity_type = #{entityType} AND entity_id = #{entityId}
ORDER BY version_no DESC
LIMIT #{limit} OFFSET #{offset}
